def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    marked = [[False] * w for _ in range(h)]
    # Find monochrome rectangular patches at least 5 by 5.
    for top in range(h):
        for color in set(grid[top]):
            valid = [grid[top][c] == color for c in range(w)]
            for bottom in range(top, h):
                if bottom > top:
                    valid = [valid[c] and grid[bottom][c] == color for c in range(w)]
                if bottom - top + 1 < 4:
                    continue
                c = 0
                while c < w:
                    if valid[c]:
                        start = c
                        while c < w and valid[c]:
                            c += 1
                        if c - start >= 5:
                            for r in range(top, bottom + 1):
                                for x in range(start, c):
                                    marked[r][x] = True
                    else:
                        c += 1
    for r in range(h):
        for c in range(w):
            if marked[r][c]:
                out[r][c] = 4
    return out
